        }
    }

    public List<Build> findByProjectId(Long projectId) {
        return buildMapper.findByProjectId(projectId);
    }

    public Build findById(Long id) {
        return buildMapper.findById(id);
    }

    public void deleteById(Long id) {
        buildMapper.deleteById(id);
    }

    private Build finish(Build build, String status, String logOutput, String artifactPath) {
        build.setStatus(status);
        build.setLogOutput(logOutput);
        build.setArtifactPath(artifactPath);
        build.setFinishedAt(LocalDateTime.now());
        buildMapper.update(build);
        return build;
    }

    private void extractArchive(String sourceZip, Path targetDir) throws IOException {
        byte[] archiveBytes = Base64.getDecoder().decode(sourceZip);
        Files.createDirectories(targetDir);
        try (ZipInputStream zip = new ZipInputStream(new ByteArrayInputStream(archiveBytes))) {
            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                Path entryPath = safeResolve(targetDir, entry.getName());
                if (entry.isDirectory()) {
                    Files.createDirectories(entryPath);
                } else {
                    if (entryPath.getParent() != null) {
                        Files.createDirectories(entryPath.getParent());
                    }
                    Files.write(entryPath, zip.readAllBytes());
                }
                zip.closeEntry();
            }
        }
    }

    private Path safeResolve(Path root, String entryName) throws IOException {
        Path resolved = root.resolve(entryName).normalize();
        if (!resolved.startsWith(root)) {
            throw new IOException("Archive entry escapes the extraction directory: " + entryName);
        }
        return resolved;
    }

    private Path locatePom(Path extractDir) {
        Path rootPom = extractDir.resolve("pom.xml");
        if (Files.isRegularFile(rootPom)) {
            return rootPom;
        }
        try (DirectoryStream<Path> children = Files.newDirectoryStream(extractDir)) {
            for (Path child : children) {
                if (Files.isDirectory(child)) {
                    Path candidate = child.resolve("pom.xml");
                    if (Files.isRegularFile(candidate)) {
                        return candidate;
                    }
                }
            }
        } catch (IOException e) {
            return null;
        }
        return null;
    }

    private String locateArtifact(Path pomDir) {
        if (pomDir == null) {
            return null;
        }
        Path outputDir = pomDir.resolve("target");
        if (!Files.isDirectory(outputDir)) {
            return null;
        }
        try (Stream<Path> entries = Files.walk(outputDir)) {
            return entries.filter(Files::isRegularFile)
                    .filter(p -> p.getFileName().toString().endsWith(".jar"))
                    .map(Path::toString)
                    .findFirst()
                    .orElse(null);
        } catch (IOException e) {
            return null;
        }
    }

    private int runMaven(Path pomFile, StringBuilder output) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder(
                "mvn", "-B", "-f", pomFile.toString(), "package", "-DskipTests");
        processBuilder.directory(pomFile.getParent().toFile());
        processBuilder.redirectErrorStream(true);

        Process process = processBuilder.start();
        Thread reader = new Thread(() -> captureOutput(process, output));
        reader.setDaemon(true);
        reader.start();
        try {
            if (!process.waitFor(BUILD_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
                destroyProcessTree(process);
                return TIMEOUT_EXIT_CODE;
            }
            return process.exitValue();
        } finally {
            if (process.isAlive()) {
                destroyProcessTree(process);
            }
            try {
                reader.join(5000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void captureOutput(Process process, StringBuilder output) {
        try (BufferedReader lines = new BufferedReader(
                new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = lines.readLine()) != null) {
                synchronized (output) {
                    output.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException ignored) {
            // stream closed when the process was terminated
        }
    }

    private void destroyProcessTree(Process process) {
        process.toHandle().descendants().forEach(ProcessHandle::destroyForcibly);
        process.destroyForcibly();
        try {
            process.waitFor(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private String snapshot(StringBuilder output) {
        synchronized (output) {
            return output.toString();
        }
    }
}
